import { LogoLink } from '@/registry/ndeko/components/navbar/_parts/logo';
import { SearchField } from '@/registry/ndeko/components/navbar/_parts/search-field';
import { ThemeToggle } from '@/registry/ndeko/components/navbar/_parts/theme-toggle';
import { MicIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

export default function Navbar10() {
  return (
    <header className='hairline-b border-border px-4 md:px-6'>
      <div className='flex h-16 items-center justify-between gap-2 sm:gap-4'>
        <div className='flex-1'>
          <LogoLink className='w-fit' />
        </div>
        <div className='grow max-sm:hidden'>
          <SearchField
            containerClassName='mx-auto w-full max-w-xs'
            end={
              <Button
                variant='ghost'
                size='icon-sm'
                aria-label='Search by voice'
                className='text-muted-foreground'
              >
                <MicIcon />
              </Button>
            }
          />
        </div>
        <div className='flex flex-1 items-center justify-end gap-2'>
          <Button variant='ghost' nativeButton={false} render={<a href='#' />}>
            Community
          </Button>
          <Button nativeButton={false} render={<a href='#' />}>
            Get started
          </Button>
          <ThemeToggle />
        </div>
      </div>
    </header>
  );
}

import { SearchIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Input, type InputProps } from '@/registry/ndeko/ui/input';

type SearchFieldProps = Omit<InputProps, 'type'> & {
  end?: React.ReactNode;
  containerClassName?: string;
};

function SearchField({
  end,
  className,
  containerClassName,
  ...props
}: SearchFieldProps) {
  const hasEnd = end !== undefined;

  return (
    <div className={cn('relative', containerClassName)}>
      <Input
        type='search'
        placeholder='Search…'
        aria-label='Search'
        className={cn('peer ps-8', hasEnd && 'pe-10', className)}
        {...props}
      />
      <span
        aria-hidden='true'
        className='text-muted-foreground/80 pointer-events-none absolute inset-y-0 start-0 flex items-center ps-2.5 peer-disabled:opacity-50'
      >
        <SearchIcon className='size-4' />
      </span>
      {hasEnd && (
        <span className='absolute inset-y-0 end-0 flex items-center pe-1.5'>
          {end}
        </span>
      )}
    </div>
  );
}

export { SearchField };

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useState } from 'react';

import { MoonIcon, SunIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

type Theme = 'light' | 'dark';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };
const EXIT_TRANSITION: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const ICON_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: {
    opacity: 0,
    scale: 0.6,
    filter: 'blur(2px)',
    transition: EXIT_TRANSITION,
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT_TRANSITION },
};

function iconVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return ICON_VARIANTS;
}

function oppositeOf(theme: Theme): Theme {
  if (theme === 'dark') {
    return 'light';
  }
  return 'dark';
}

function ThemeIcon({ theme }: { theme: Theme }) {
  if (theme === 'dark') {
    return <MoonIcon />;
  }
  return <SunIcon />;
}

function ThemeToggle() {
  const [theme, setTheme] = useState<Theme>('light');
  const shouldReduceMotion = useReducedMotion();
  const iconVariants = iconVariantsOf(shouldReduceMotion);
  const nextTheme = oppositeOf(theme);

  function toggleTheme() {
    setTheme(oppositeOf);
  }

  return (
    <Button
      variant='ghost'
      size='icon'
      aria-label={`Switch to ${nextTheme} mode`}
      onClick={toggleTheme}
      className='text-muted-foreground'
    >
      <span className='relative flex'>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.span
            key={theme}
            className='flex'
            variants={iconVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            <ThemeIcon theme={theme} />
          </motion.span>
        </AnimatePresence>
      </span>
    </Button>
  );
}

export { ThemeToggle };
